          translation: "फिर भी हे देवि! यदि इस समय आप मुझे वर देना चाहती हैं तो हे शिवे! सृष्टिकार्यमें आनेवाले मेरे सभी विघ्न क्षीण होकर नष्ट हो जायँ। जो भी लोग वाग्भव बीजमन्त्रके उपासक हों, उनके कार्योंकी सिद्धि शीघ्र ही हो जाय। हे देवि! जो लोग इस संवादको पढ़ें और दूसरोंको सुनायें, उनके लिये इस लोकमें भोग तथा मोक्ष सुलभ हो जायँ। हे शिवे! उन्हें पूर्वजन्मोंकी स्मृति बनी रहे और वे वक्तृता तथा वाणी-सौष्ठवसे सम्पन्न रहें। उन्हें ज्ञानकी सिद्धि हो तथा कर्मयोगकी भी सिद्धि प्राप्त हो, साथ ही उनके यहाँ पुत्र-पौत्रकी समृद्धि निरन्तर होती रहे—यही मेरा आपसे निवेदन है॥ २०—२४॥",
