          sanskrit: "दैवतानि शृणु प्राज्ञ तेषामेवानुपूर्वश:। आग्नेयं प्रथमं प्रोक्तं प्राजापत्यं द्वितीयकम्॥ २० तृतीयं च तथा सौम्यमीशानं च चतुर्थकम्। सावित्रं पञ्चमं प्रोक्तं षष्ठमादित्यदैवतम्॥ २१ बार्हस्पत्यं सप्तमं तु मैत्रावरुणमष्टमम्। नवमं भगदैवत्यं दशमं चार्यमेश्वरम्॥ २२ गणेशमेकादशकं त्वाष्ट्रं द्वादशकं स्मृतम्। पौष्णं त्रयोदशं प्रोक्तमैन्द्राग्नं च चतुर्दशम्॥ २३ वायव्यं पञ्चदशकं वामदैव्यं च षोडशम्। मैत्रावरुणिदैवत्यं प्रोक्तं सप्तदशाक्षरम्॥ २४ अष्टादशं वैश्वदेवमूनविंशं तु मातृकम्। वैष्णवं विंशतितमं वसुदैवतमीरितम्॥ २५ एकविंशतिसंख्याकं द्वाविंशं रुद्रदैवतम्। त्रयोविंशं च कौबेरमाश्विनं तत्त्वसंख्यकम्॥ २६ चतुर्विंशतिवर्णानां देवतानां च सङ्ग्रह:। कथित: परमश्रेष्ठो महापापैकशोधन:। यदाकर्णनमात्रेण साङ्गं जाप्यफलं मुने॥ २७",
          transliteration: "daivatāni śṛṇu prājña teṣāmevānupūrvaśa:| āgneyṃ prathamṃ proktṃ prājāpatyṃ dvitīyakam|| 20 tṛtīyṃ ca tathā saumyamīśānṃ ca caturthakam| sāvitrṃ pañcamṃ proktṃ ṣaṣṭhamādityadaivatam|| 21 bārhaspatyṃ saptamṃ tu maitrāvaruṇamaṣṭamam| navamṃ bhagadaivatyṃ daśamṃ cāryameśvaram|| 22 gaṇeśamekādaśakṃ tvāṣṭrṃ dvādaśakṃ smṛtam| pauṣṇṃ trayodaśṃ proktamaindrāgnṃ ca caturdaśam|| 23 vāyavyṃ pañcadaśakṃ vāmadaivyṃ ca ṣoḍaśam| maitrāvaruṇidaivatyṃ proktṃ saptadaśākṣaram|| 24 aṣṭādaśṃ vaiśvadevamūnaviṃśṃ tu mātṛkam| vaiṣṇavṃ viṃśatitamṃ vasudaivatamīritam|| 25 ekaviṃśatisṃkhyākṃ dvāviṃśṃ rudradaivatam| trayoviṃśṃ ca kauberamāśvinṃ tattvasṃkhyakam|| 26 caturviṃśativarṇānāṃ devatānāṃ ca saṅgraha:| kathita: paramaśreṣṭho mahāpāpaikaśodhana:| yadākarṇanamātreṇa sāṅgṃ jāpyaphalṃ mune|| 27",
          translation: "हे प्राज्ञ! अब क्रमश: उन वर्णोंके देवताओंके नाम सुनिये। पहले वर्णके देवता अग्नि, दूसरेके प्रजापति, तीसरेके चन्द्रमा, चौथेके ईशान, पाँचवेंके सविता, छठेके आदित्य, सातवेंके बृहस्पति, आठवेंके मित्रावरुण, नौवेंके भग, दसवेंके ईश्वर, ग्यारहवेंके गणेश, बारहवेंके त्वष्टा, तेरहवेंके पूषा, चौदहवेंके इन्द्राग्नि, पन्द्रहवेंके वायु, सोलहवेंके वामदेव, सत्रहवेंके मित्रावरुण, अठारहवेंके विश्वेदेव, उन्नीसवेंके मातृक, बीसवेंके विष्णु, इक्कीसवेंके वसु, बाईसवेंके रुद्र, तेईसवेंके कुबेर और चौबीसवें वर्णके देवता अश्विनीकुमार कहे गये हैं। हे मुने! इस प्रकार मैंने गायत्रीके चौबीस वर्णोंके देवताओंका वर्णन कर दिया। यह नामसंग्रह परम श्रेष्ठ और महान् पापोंका विनाश करनेवाला है, जिसके श्रवणमात्रसे सांगोपांग गायत्रीजपका फल प्राप्त हो जाता है॥ २०—२७॥",
          hindi: "हे प्राज्ञ! अब क्रमश: उन वर्णोंके देवताओंके नाम सुनिये। पहले वर्णके देवता अग्नि, दूसरेके प्रजापति, तीसरेके चन्द्रमा, चौथेके ईशान, पाँचवेंके सविता, छठेके आदित्य, सातवेंके बृहस्पति, आठवेंके मित्रावरुण, नौवेंके भग, दसवेंके ईश्वर, ग्यारहवेंके गणेश, बारहवेंके त्वष्टा, तेरहवेंके पूषा, चौदहवेंके इन्द्राग्नि, पन्द्रहवेंके वायु, सोलहवेंके वामदेव, सत्रहवेंके मित्रावरुण, अठारहवेंके विश्वेदेव, उन्नीसवेंके मातृक, बीसवेंके विष्णु, इक्कीसवेंके वसु, बाईसवेंके रुद्र, तेईसवेंके कुबेर और चौबीसवें वर्णके देवता अश्विनीकुमार कहे गये हैं। हे मुने! इस प्रकार मैंने गायत्रीके चौबीस वर्णोंके देवताओंका वर्णन कर दिया। यह नामसंग्रह परम श्रेष्ठ और महान् पापोंका विनाश करनेवाला है, जिसके श्रवणमात्रसे सांगोपांग गायत्रीजपका फल प्राप्त हो जाता है॥ २०—२७॥",
          explanation: "श्रीमद्देवीभागवतमहापुराण द्वादश स्कन्ध (गायत्री-रहस्य, मणिद्वीप-वर्णन एवं देवी-माहात्म्य) का श्लोक 11। शाक्तपरम्पराके इस परम ग्रन्थमें परात्पर भगवती जगदम्बाकी शक्ति, सृष्टि-स्थिति-संहार तथा मुक्तिप्रद स्वरूपका प्रामाणिक वर्णन है।",
