          sanskrit: "तत्त्वान्येतानि वर्णानां क्रमश: कीर्तितानि तु। अत: परं प्रवक्ष्यामि वर्णमुद्रा: क्रमेण तु॥ १३ सुमुखं सम्पुटं चैव विततं विस्तृतं तथा। द्विमुखं त्रिमुखं चैव चतु:पञ्चमुखं तथा॥ १४ षण्मुखाधोमुखं चैव व्यापकाञ्जलिकं तथा। शकटं यमपाशं च ग्रथितं सन्मुखोन्मुखम्॥ १५ विलम्बं मुष्टिकं चैव मत्स्यं कूर्मं वराहकम्। सिंहाक्रान्तं महाक्रान्तं मुद्गरं पल्लवं तथा॥ १६ त्रिशूलयोनी सुरभिश्चाक्षमाला च लिङ्गकम्। अम्बुजं च महामुद्रास्तुर्यरूपा: प्रकीर्तिता:॥ १७ इत्येता: कीर्तिता मुद्रा वर्णानां ते महामुने। महापापक्षयकरा: कीर्तिदा: कान्तिदा मुने॥ १८",
          transliteration: "tattvānyetāni varṇānāṃ kramaśa: kīrtitāni tu| ata: parṃ pravakṣyāmi varṇamudrā: krameṇa tu|| 13 sumukhṃ sampuṭṃ caiva vitatṃ vistṛtṃ tathā| dvimukhṃ trimukhṃ caiva catu:pañcamukhṃ tathā|| 14 ṣaṇmukhādhomukhṃ caiva vyāpakāñjalikṃ tathā| śakaṭṃ yamapāśṃ ca grathitṃ sanmukhonmukham|| 15 vilambṃ muṣṭikṃ caiva matsyṃ kūrmṃ varāhakam| siṃhākrāntṃ mahākrāntṃ mudgarṃ pallavṃ tathā|| 16 triśūlayonī surabhiścākṣamālā ca liṅgakam| ambujṃ ca mahāmudrāsturyarūpā: prakīrtitā:|| 17 ityetā: kīrtitā mudrā varṇānāṃ te mahāmune| mahāpāpakṣayakarā: kīrtidā: kāntidā mune|| 18",
          translation: "[हे नारद!] अब मैं क्रमश: वर्णोंकी मुद्राओंका वर्णन करूँगा। सुमुख, सम्पुट, वितत, विस्तृत, द्विमुख, त्रिमुख, चतुर्मुख, पंचमुख, षण्मुख, अधोमुख, व्यापकांजलि, शकट, यमपाश, ग्रथित, सन्मुखोन्मुख, विलम्ब, मुष्टिक, मत्स्य, कूर्म, वराह, सिंहाक्रान्त, महाक्रान्त, मुद्गर तथा पल्लव—गायत्रीके अक्षरोंकी ये चौबीस मुद्राएँ हैं। त्रिशूल, योनि, सुरभि, अक्षमाला, लिंग और अम्बुज—ये महामुद्राएँ गायत्रीके चौथे चरणकी कही गयी हैं। हे महामुने! गायत्रीके वर्णोंकी इन मुद्राओंको मैंने आपको बता दिया। हे मुने! ये मुद्राएँ महान् पापोंका नाश करनेवाली, कीर्ति देनेवाली तथा कान्ति प्रदान करनेवाली हैं॥ १३—१८॥",
          hindi: "[हे नारद!] अब मैं क्रमश: वर्णोंकी मुद्राओंका वर्णन करूँगा। सुमुख, सम्पुट, वितत, विस्तृत, द्विमुख, त्रिमुख, चतुर्मुख, पंचमुख, षण्मुख, अधोमुख, व्यापकांजलि, शकट, यमपाश, ग्रथित, सन्मुखोन्मुख, विलम्ब, मुष्टिक, मत्स्य, कूर्म, वराह, सिंहाक्रान्त, महाक्रान्त, मुद्गर तथा पल्लव—गायत्रीके अक्षरोंकी ये चौबीस मुद्राएँ हैं। त्रिशूल, योनि, सुरभि, अक्षमाला, लिंग और अम्बुज—ये महामुद्राएँ गायत्रीके चौथे चरणकी कही गयी हैं। हे महामुने! गायत्रीके वर्णोंकी इन मुद्राओंको मैंने आपको बता दिया। हे मुने! ये मुद्राएँ महान् पापोंका नाश करनेवाली, कीर्ति देनेवाली तथा कान्ति प्रदान करनेवाली हैं॥ १३—१८॥",
          explanation: "श्रीमद्देवीभागवतमहापुराण द्वादश स्कन्ध (गायत्री-रहस्य, मणिद्वीप-वर्णन एवं देवी-माहात्म्य) का श्लोक 15। शाक्तपरम्पराके इस परम ग्रन्थमें परात्पर भगवती जगदम्बाकी शक्ति, सृष्टि-स्थिति-संहार तथा मुक्तिप्रद स्वरूपका प्रामाणिक वर्णन है।",
