          translation: "नारदजी बोले—हे स्वामिन्! हे सम्पूर्ण जगत्के नाथ! हे प्रभो! हे चौंसठ कलाओंके ज्ञाता! हे योगवेत्ताओंमें श्रेष्ठ! मनुष्य किस पुण्यकर्मसे पापमुक्त हो सकता है, किस प्रकार ब्रह्मरूपत्व प्राप्त कर सकता है और किस कर्मसे उसका देह देवतारूप तथा विशेषरूपसे मन्त्ररूप हो सकता है? हे प्रभो! उस कर्मके विषयमें साथ ही विधिपूर्वक न्यास, ऋषि, छन्द, अधिदेवता तथा ध्यानको विधिवत् सुनना चाहता हूँ॥ १—३॥",
